import{_ as n,o as s,c as r,a3 as a}from"./chunks/framework.I6s8z2kk.js";const u=JSON.parse('{"title":"Plans and subscriptions","description":"","frontmatter":{},"headers":[],"relativePath":"user/admin/billing.md","filePath":"user/admin/billing.md"}'),e={name:"user/admin/billing.md"};function i(o,t,l,d,c,g){return s(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="plans-and-subscriptions" tabindex="-1">Plans and subscriptions <a class="header-anchor" href="#plans-and-subscriptions" aria-label="Permalink to &quot;Plans and subscriptions&quot;">​</a></h1><p>Centers can subscribe to a <strong>plan</strong>. Plans are managed with the plan permissions; subscriptions with the <strong>change subscriptions</strong> permission.</p><h2 id="plans" tabindex="-1">Plans <a class="header-anchor" href="#plans" aria-label="Permalink to &quot;Plans&quot;">​</a></h2><p>A plan has a name, price in SAR, a <strong>billing interval</strong> (monthly or yearly), optional <strong>trial days</strong>, features and limits, and a status (<strong>Active</strong> or <strong>Inactive</strong>). Centers can only subscribe to <strong>active</strong> plans.</p><p>Create and edit plans under <strong>Plans</strong>, switch a plan on or off, and attach <strong>features</strong> and <strong>limits</strong> to it. The catalog of features and limits itself needs the <strong>manage catalog</strong> permission.</p><h2 id="subscriptions" tabindex="-1">Subscriptions <a class="header-anchor" href="#subscriptions" aria-label="Permalink to &quot;Subscriptions&quot;">​</a></h2><p><strong>Subscriptions</strong> lists every center&#39;s subscription; sort it by <strong>Starts</strong> or <strong>Ends</strong>. You can also change a center&#39;s subscription from its page. Centers can subscribe and cancel on their own from the dashboard (see <a href="./../center/overview">Center overview</a>).</p><table tabindex="0"><thead><tr><th>Status</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Trialing</strong></td><td>In a free trial</td></tr><tr><td><strong>Active</strong></td><td>Paid and running</td></tr><tr><td><strong>Pending</strong></td><td>Waiting for payment</td></tr><tr><td><strong>Canceled</strong></td><td>Stopped by the owner</td></tr><tr><td><strong>Expired</strong></td><td>Ran past its end date</td></tr></tbody></table><ul><li>A center cannot hold two active or trialing subscriptions to the same plan.</li><li>A subscription lasts one interval from its start. <strong>Renewing</strong> starts a new one from the previous end date, with no trial.</li><li>Only the center <strong>owner</strong> can cancel.</li><li>There is no VAT, invoicing or proration in subscriptions.</li><li>Unpaid subscriptions are released automatically.</li></ul>',9)])])}const h=n(e,[["render",i]]);export{u as __pageData,h as default};
